import{c as e,Q as o,j as s,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"output-compress 自動量測 × 自動進化機制設計","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-17-output-compress-auto-evolution-design.md","filePath":"research/reports/2026-07-17-output-compress-auto-evolution-design.md","lastUpdated":1785909234000}'),n={name:"research/reports/2026-07-17-output-compress-auto-evolution-design.md"};function a(i,t,l,d,c,p){return o(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="output-compress-自動量測-×-自動進化機制設計" tabindex="-1">output-compress 自動量測 × 自動進化機制設計 <a class="header-anchor" href="#output-compress-自動量測-×-自動進化機制設計" aria-label="Permalink to &quot;output-compress 自動量測 × 自動進化機制設計&quot;">​</a></h1><blockquote><p>2026-07-17，使用者指示「收集更多數據優化 SKILL + 評估自動量測/自動優化/進化機制」。 學術接地：11 篇壓縮保真論文（見 research/papers/ 2026-07-17 歸檔批次）；本設計直接消費其中 2606.29251（decontextualization）、2503.19114（groundedness 掉分）、2602.09789（scaling paradox）。</p></blockquote><h2 id="_0-設計約束-不可違反的既有裁決" tabindex="-1">0. 設計約束（不可違反的既有裁決） <a class="header-anchor" href="#_0-設計約束-不可違反的既有裁決" aria-label="Permalink to &quot;0. 設計約束（不可違反的既有裁決）&quot;">​</a></h2><ol><li><strong>判斷 vs 決定公理</strong>（core.md）：LLM 只做壓縮判斷與提案撰寫；量測、門檻、觸發全部確定性程序。</li><li><strong>2026-07-16 使用者裁決（選項 a）</strong>：AUTO 維持 advisory；enforcement 升級<strong>只能</strong>在 2026-08-13 複查且零筆日 ≥20/28 時進入裁決——本機制<strong>不預支該決定</strong>，只讓複查時的資料更完整。</li><li>提案不自動套用：一律 EVOLUTION-QUEUE <code>status: proposed</code>，Routine G ≤2 提案/週上限沿用。</li></ol><h2 id="_1-三層架構" tabindex="-1">1. 三層架構 <a class="header-anchor" href="#_1-三層架構" aria-label="Permalink to &quot;1. 三層架構&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌ 採樣層（多掛點餵 log；不新增 enforcement hook）</span></span>
<span class="line"><span>│   fidelity-check.py --log →  evolution/compress-log.jsonl</span></span>
<span class="line"><span>├ 量測層（確定性聚合 + 固定門檻 verdict）</span></span>
<span class="line"><span>│   scripts/compress-metrics.py --json → V1–V5 verdicts</span></span>
<span class="line"><span>└ 進化層（週節奏；judgment 只在提案撰寫）</span></span>
<span class="line"><span>    Routine G 消費 verdicts → EVOLUTION-QUEUE proposed → 人工審 → skill-evolution:apply</span></span></code></pre></div><h2 id="_2-各層落地內容-本日已實作-✅-提案-⏳" tabindex="-1">2. 各層落地內容（本日已實作 ✅ / 提案 ⏳） <a class="header-anchor" href="#_2-各層落地內容-本日已實作-✅-提案-⏳" aria-label="Permalink to &quot;2. 各層落地內容（本日已實作 ✅ / 提案 ⏳）&quot;">​</a></h2><h3 id="採樣層——增加數據量-不越權" tabindex="-1">採樣層——增加數據量，不越權 <a class="header-anchor" href="#採樣層——增加數據量-不越權" aria-label="Permalink to &quot;採樣層——增加數據量，不越權&quot;">​</a></h3><ul><li>✅ <strong>grounded_pct 入 log</strong>：每筆新增接地率代理欄（詞級 containment，只刪不改寫 ⇒ ≈100）——2503.19114 groundedness 軸的零成本確定性代理。</li><li>✅ <strong>hedge_counts 入失真閘</strong>：decontextualization（2606.29251）成為第 9 個白名單類別；FAIL 樣本本身就是新數據維度（missing_keys 分布多了一類）。</li><li>✅ <strong>委派壓縮 context 標記</strong>（SKILL §7 既有）：<code>delegated-*</code> vs inline 對照組。</li><li>⏳ <strong>Routine RECORD 採樣擴充</strong>（提案）：Routine C 已有 Step -1 強制 gate+log；比照擴到 A/B/E/F/G 的 RECORD——routine 是<strong>確定性 spec 驅動</strong>，這裡加「必跑」不是 enforcement hook、是 spec 條款（07-16 分層證據：routine 遵守 AUTO、互動式忽略——把守規矩的一側採樣最大化）。</li><li>✅ <strong>一般 session 機會日誌</strong>（2026-07-17 使用者指示「一般 session 也要自動量測」後落地）：「<strong>量測</strong> enforcement」與「<strong>壓縮</strong> enforcement」分離——前者零 LLM 參與零失真風險，內嵌既有 <code>usage-delegation-gate.sh</code>（PreToolUse Agent|Workflow，<strong>零新增 settings.json wiring</strong>）：≥500B 派工 prompt 機械記 bytes/coverage 近似/契約齊備/would_compress → <code>evolution/compress-opportunity-log.jsonl</code>（merge=union）。這補上執行率的<strong>分母</strong>（compress-log 只有自願壓的分子，G8/G13 雙重樣本受限的結構性解法）；純記錄無提醒，原 queue 指出的循環依賴（hook 判斷「該壓沒壓」須先跑 coverage）不存在——hook 不判斷、只記錄。</li><li>❌ <strong>仍不做</strong>：壓縮 enforcement（強制模型壓縮 / block 未壓派工）——等 08-13 裁決，V3/V4/V6 就是該裁決的輸入。</li></ul><h3 id="量測層——scripts-compress-metrics-py-✅" tabindex="-1">量測層——<code>scripts/compress-metrics.py</code> ✅ <a class="header-anchor" href="#量測層——scripts-compress-metrics-py-✅" aria-label="Permalink to &quot;量測層——\`scripts/compress-metrics.py\` ✅&quot;">​</a></h3><p>固定門檻 verdict（改動須同步本檔）：</p><table tabindex="0"><thead><tr><th>ID</th><th>條件</th><th>action_hint</th></tr></thead><tbody><tr><td>V1</td><td>組合 n≥5 且 pass_rate&lt;0.90</td><td>降該組合壓縮上限提案</td></tr><tr><td>V2</td><td>組合 n≥5 且 grounded 中位 &lt;95</td><td>改寫滲入 → GOTCHAS + 重申鐵則</td></tr><tr><td>V3</td><td>零筆日 ≥20/28</td><td>觸發 08-13 複查裁決條件</td></tr><tr><td>V4</td><td>互動式 n=0 且 routine n&gt;0</td><td>advisory 分層失效證據</td></tr><tr><td>V5</td><td>delegated pass &lt; inline（雙側 n≥5）</td><td>SKILL §7 撤除候選</td></tr><tr><td>V6</td><td>would_compress 機會 ≥10 且執行率 &lt;0.30</td><td>AUTO 對互動 session 失效的分母級證據（08-13 複查輸入）</td></tr></tbody></table><p><strong>首跑實測（2026-07-17，28 天窗、31 筆）</strong>：V1×2（<code>full×subagent-prompt</code> 0.727、<code>lite×routine-f</code> 0.333）+ V3（22/28）。V1 兩筆為真訊號、可立即供 Routine G 撰提案；V3 依約束 0-2 不裁決、僅累積。</p><h3 id="進化層——routine-g-接線-✅" tabindex="-1">進化層——Routine G 接線 ✅ <a class="header-anchor" href="#進化層——routine-g-接線-✅" aria-label="Permalink to &quot;進化層——Routine G 接線 ✅&quot;">​</a></h3><p>ROUTINE-G spec IDENTIFY 段加：<code>python3 scripts/compress-metrics.py --json</code> 必跑，verdict 非空 → 對應提案候選（計入 ≤2/週）；V1/V2 需附 log 樣本行佐證（judgment 撰寫、機械數字直引 verdict JSON）。</p><h2 id="_3-反-eval-hack-與失效偵測" tabindex="-1">3. 反 eval-hack 與失效偵測 <a class="header-anchor" href="#_3-反-eval-hack-與失效偵測" aria-label="Permalink to &quot;3. 反 eval-hack 與失效偵測&quot;">​</a></h2><ul><li><strong>量測器不可被壓縮行為討好</strong>：pass_rate 分母 = 全部 log 筆（含 fail），模型「少記 fail」會使 V3/V4 惡化——兩個 verdict 互為對抗。</li><li><strong>門檻改動紀律</strong>：V1–V5 門檻是「決定」，改動 = harness 修改 → 失敗簽名 ≥2 次獨立重現才動（harness-loop.md 觸發門檻）。</li><li><strong>grounded_pct 的已知限界</strong>：詞級 containment 對「換序造成語義反轉」盲（fidelity 閘的 date/number multiset 已部分覆蓋）；它是趨勢指標非逐筆 oracle。</li><li><strong>Falsifiable prediction</strong>：hedge 類上線後 30 天，<code>missing_keys</code> 含 <code>hedge_counts</code> 的 FAIL ≥1 筆（證明軸有效）；若 0 筆且人工抽查 10 樣本無 hedge 剝離 → 詞表過鬆，收窄。</li></ul><h2 id="_4-待辦-邊界" tabindex="-1">4. 待辦 / 邊界 <a class="header-anchor" href="#_4-待辦-邊界" aria-label="Permalink to &quot;4. 待辦 / 邊界&quot;">​</a></h2><ul><li>eval fixture 三臂（SKILL §5 既有待辦）仍缺；compress-metrics 是 telemetry 路線、fixture 是 benchmark 路線，互補不互代。</li><li>EDU 級壓縮單位（2512.14244）列 backlog，等 V1 訊號證明行級刪除不夠再議。</li><li>2026-08-13 複查時的裁決輸入 = <code>compress-metrics.py --json</code>（V3/V4 即該複查指定的分層量測軸）。</li></ul>`,19)])])}const h=e(n,[["render",a]]);export{g as __pageData,h as default};
